WITH valid AS (SELECT *, INITCAP(TRIM(txn_type)) AS txn_type_title, COALESCE(merchant, 'NONE') AS merchant_clean FROM transactions WHERE amount > 2500), cleaned AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, txn_type_title, merchant_clean, SUBSTRING(txn_type, 1, 3) AS txn_type_prefix, COALESCE(merchant, 'DIRECT') AS resolved_merchant FROM valid WHERE txn_time > DATE '2023-08-09'), with_windows AS (SELECT id, txn_type, is_flagged, txn_type_title, resolved_merchant, SUM(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_amount, MAX(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_amount, MIN(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, COUNT(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_amount FROM cleaned WHERE amount BETWEEN 3700 AND 4000), cleaned_transactions AS (SELECT *, CASE WHEN running_count_amount >= 14 THEN 'High' WHEN running_count_amount >= 4 THEN 'Medium' ELSE 'Low' END AS running_count_amount_level, COALESCE(running_sum_amount, 0) AS running_sum_amount_filled FROM with_windows WHERE txn_type = 'FEE'), deduped AS (SELECT * FROM cleaned_transactions QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY running_max_amount ASC NULLS LAST, id ASC) = 1), deduped_transactions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY running_sum_amount_filled ASC NULLS FIRST, id ASC) AS dedup_rank FROM deduped) ranked WHERE dedup_rank = 1), latest AS (SELECT id, txn_type_title, resolved_merchant, running_max_amount, running_min_amount, running_count_amount, running_sum_amount_filled FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY running_sum_amount_filled ASC, id ASC) AS rn FROM deduped_transactions) ranked WHERE rn = 1) SELECT id, txn_type_title, running_max_amount, running_min_amount, running_count_amount, running_sum_amount_filled FROM latest
